<script setup>
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import EChart from '../../components/EChart.vue'
import PageHeader from '../../components/common/PageHeader.vue'
import SectionCard from '../../components/common/SectionCard.vue'
import StatCard from '../../components/common/StatCard.vue'
import EmptyState from '../../components/common/EmptyState.vue'
import { apiMessage } from '../../api/http.js'
import { getOverview, getMonthlyCollection, getFeeComposition, getBillStatus, getOccupancy, getOverdueTop, getResidenceDashboard, getRentalDashboard } from '../../api/dashboard.js'

const year = ref(2026), loading = ref(false), overview = ref({}), monthly = ref([]), fees = ref([]), status = ref([]), occupancy = ref([]), overdue = ref([]), residence = ref({}), rental = ref({})
const money = value => new Intl.NumberFormat('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value || 0)
const percent = value => `${Number(value || 0).toFixed(2)}%`
const monthOption = computed(() => ({ tooltip: { trigger: 'axis' }, legend: { data: ['应收', '实收', '收缴率'] }, grid: { left: 58, right: 55, top: 42, bottom: 35 }, xAxis: { type: 'category', data: monthly.value.map(item => `${item.month}月`) }, yAxis: [{ type: 'value' }, { type: 'value', axisLabel: { formatter: '{value}%' } }], series: [{ name: '应收', type: 'bar', data: monthly.value.map(item => item.receivableAmount), itemStyle: { color: '#74b8ad', borderRadius: [4, 4, 0, 0] } }, { name: '实收', type: 'bar', data: monthly.value.map(item => item.receivedAmount), itemStyle: { color: '#167d72', borderRadius: [4, 4, 0, 0] } }, { name: '收缴率', type: 'line', yAxisIndex: 1, smooth: true, data: monthly.value.map(item => item.collectionRatePercent), itemStyle: { color: '#b77a22' } }] }))
const pie = (rows, labels = {}) => ({ tooltip: { trigger: 'item' }, legend: { bottom: 0, type: 'scroll' }, series: [{ type: 'pie', radius: ['45%', '70%'], data: (rows || []).map(item => { const key = item.status || item.feeCode || item.occupancyStatus || item.label; return { name: labels[key] || item.feeName || key, value: item.receivableAmount || item.billCount || item.propertyCount || item.value } }), label: { formatter: '{b}\n{d}%' } }] })
const feeOption = computed(() => pie(fees.value)); const statusOption = computed(() => pie(status.value, { PAID: '已缴清', PARTIALLY_PAID: '部分缴费', OVERDUE: '已逾期', UNPAID: '未缴' })); const occupancyOption = computed(() => pie(occupancy.value, { OWNER_OCCUPIED: '业主自住', TENANT_OCCUPIED: '租户居住', AVAILABLE_FOR_RENT: '可出租', VACANT: '空置' })); const relationOption = computed(() => pie(residence.value.relationDistribution, { SELF: '本人', SPOUSE: '配偶', PARENT: '父母', CHILD: '子女', SIBLING: '兄弟姐妹', ROOMMATE: '合租人', OTHER: '其他' })); const communityOption = computed(() => pie(residence.value.communityDistribution)); const rentalModeOption = computed(() => pie(rental.value.modeDistribution, { SELF: '业主直租', AGENCY: '中介代理' })); const rentalStatusOption = computed(() => pie(rental.value.statusDistribution, { PUBLISHED: '挂牌中', RENTED: '已出租', CLOSED: '已关闭', EXPIRED: '已过期' }))
async function load() { loading.value = true; try { [overview.value, monthly.value, fees.value, status.value, occupancy.value, overdue.value, residence.value, rental.value] = await Promise.all([getOverview(year.value), getMonthlyCollection(year.value), getFeeComposition(year.value), getBillStatus(year.value), getOccupancy(), getOverdueTop(), getResidenceDashboard(), getRentalDashboard(year.value)]) } catch (error) { ElMessage.error(apiMessage(error, '数据总览加载失败')) } finally { loading.value = false } }
onMounted(load)
</script>

<template>
  <section v-loading="loading" class="dashboard-page">
    <PageHeader title="数据总览" description="从房产、居住、收费和运营四个维度了解当前管理范围；所有指标均由后端按当前账号范围汇总。"><template #actions><el-select v-model="year" class="year-select" @change="load"><el-option :value="2026" label="2026 年"/></el-select></template></PageHeader>
    <div class="overview-row"><StatCard label="管理房产" :value="overview.propertyCount || 0" :helper="`入住率 ${percent(overview.occupancyRatePercent)}`" tone="primary"/><StatCard label="本年实收" :value="`¥ ${money(overview.receivedAmount)}`" :helper="`应收 ¥ ${money(overview.receivableAmount)}`"/><StatCard label="待跟进欠费" :value="`¥ ${money(overview.outstandingAmount)}`" :helper="`收缴率 ${percent(overview.collectionRatePercent)}`" tone="warning"/><StatCard label="当前居住" :value="residence.activeResidentCount || 0" :helper="`${residence.responsibleCount || 0} 位主要居住人`"/></div>
    <SectionCard title="收费趋势" description="应收、实收和收缴率随真实账单数据更新。"><EChart :option="monthOption" height="330px"/></SectionCard>
    <div class="analysis-grid"><SectionCard title="费用构成" description="按收费项目汇总本年应收金额。"><EChart :option="feeOption" height="280px"/></SectionCard><SectionCard title="状态分布" description="用于快速识别需要跟进的账单和房产状态。"><el-tabs><el-tab-pane label="账单"><EChart :option="statusOption" height="230px"/></el-tab-pane><el-tab-pane label="房产"><EChart :option="occupancyOption" height="230px"/></el-tab-pane></el-tabs></SectionCard></div>
    <div class="operations-grid"><SectionCard title="居民服务概况" description="居住关系与房产占用情况。"><div class="line-metrics"><span>业主自住 <b>{{ residence.ownerOccupiedCount || 0 }}</b></span><span>租户居住 <b>{{ residence.tenantOccupiedCount || 0 }}</b></span><span>可出租 <b>{{ residence.availableForRentCount || 0 }}</b></span><span>空置 <b>{{ residence.vacantCount || 0 }}</b></span></div><div class="mini-charts"><EChart :option="relationOption" height="210px"/><EChart :option="communityOption" height="210px"/></div></SectionCard><SectionCard title="待跟进账单" description="按欠费金额排序，便于优先处理。"><el-table v-if="overdue.length" :data="overdue" max-height="320"><el-table-column prop="communityName" label="小区"/><el-table-column prop="propertyNo" label="房产"/><el-table-column label="账期" width="90"><template #default="{row}">{{ row.billingMonth }} 月</template></el-table-column><el-table-column label="欠费" width="120"><template #default="{row}">¥ {{ money(row.outstandingAmount) }}</template></el-table-column></el-table><EmptyState v-else title="当前没有逾期账单" description="已逾期的账单会按欠费金额显示在这里。"/></SectionCard></div>
    <SectionCard title="租赁挂牌概况" description="挂牌数据以当前管理范围内的真实挂牌记录为准。"><div class="rental-row"><div class="line-metrics"><span>当前挂牌 <b>{{ rental.currentPublishedCount || 0 }}</b></span><span>本期已出租挂牌 <b>{{ rental.rentedInPeriodCount || 0 }}</b></span><span>平均月租 <b>¥ {{ money(rental.averageMonthlyRent) }}</b></span><span>平均挂牌天数 <b>{{ Number(rental.averageListingDays || 0).toFixed(1) }} 天</b></span></div><div class="rental-charts"><EChart :option="rentalModeOption" height="210px"/><EChart :option="rentalStatusOption" height="210px"/></div></div></SectionCard>
  </section>
</template>
<style scoped>.dashboard-page{display:grid;gap:18px}.year-select{width:112px}.overview-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.analysis-grid,.operations-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.line-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:12px;overflow:hidden}.line-metrics span{padding:13px;background:#fbfdfc;color:var(--ink-500);font-size:12px}.line-metrics b{float:right;color:var(--ink-900);font-size:14px;font-variant-numeric:tabular-nums}.mini-charts,.rental-charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:12px}.rental-row{display:grid;grid-template-columns:minmax(260px,.8fr) minmax(0,1.2fr);gap:22px;align-items:center}.rental-charts{margin-top:0}@media(max-width:1120px){.overview-row{grid-template-columns:repeat(2,minmax(0,1fr))}.rental-row,.analysis-grid,.operations-grid{grid-template-columns:1fr}}@media(max-width:620px){.overview-row,.mini-charts,.rental-charts,.line-metrics{grid-template-columns:1fr}}</style>
